package com.campus.trade.ai.dispute;
import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.assertThatThrownBy;
class DisputeAgentValidatorTest { private final DisputeAgentValidator v=new DisputeAgentValidator(); private DisputeAgentResult base(DisputeAgentAction a){return new DisputeAgentResult(a,0.8,DisputeAgentLiability.UNCLEAR,List.of("reason"),List.of(),List.of("photo"),false,List.of(),"summary");} @Test void fabricatedQuoteRejected(){var x=new DisputeAgentResult(DisputeAgentAction.REJECT,0.8,DisputeAgentLiability.RESPONDENT,List.of("x"),List.of(new DisputeAgentResult.VerifiedFact("statement","not-present")),List.of(),false,List.of(new DisputeAgentResult.RuleRef("DISPUTE-001","2026-01","x","x")),"x");assertThatThrownBy(()->v.validate(x,Set.of("DISPUTE-001@2026-01"),Map.of("statement","actual"))).isInstanceOf(DisputeAgentOutputInvalidException.class);} @Test void rejectNeedsRule(){assertThatThrownBy(()->v.validate(base(DisputeAgentAction.REJECT),Set.of(),Map.of())).isInstanceOf(DisputeAgentOutputInvalidException.class);} @Test void needMoreNeedsEvidence(){var base=base(DisputeAgentAction.NEED_MORE);var x=new DisputeAgentResult(base.suggestedAction(),base.confidence(),base.liability(),base.reasons(),base.verifiedFacts(),List.of(),base.suggestedRestock(),base.ruleRefs(),base.adminSummary());assertThatThrownBy(()->v.validate(x,Set.of(),Map.of())).isInstanceOf(DisputeAgentOutputInvalidException.class);} }
